    /**
     * Returns an inline, decorative SVG icon.
     *
     * @param string $name key of PATHS
     * @return string
     */
    public static function svg(string $name): string {
        if (!isset(self::PATHS[$name])) {
            return '';
        }
        return '<svg class="clms-icon clms-icon-' . $name . '" width="1em" height="1em" viewBox="0 0 24 24" '
            . 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
            . 'stroke-linejoin="round" aria-hidden="true" focusable="false">' . self::PATHS[$name] . '</svg>';
    }
